// TypeScript: interface User { name: string; age: number; email?: string }
// Validate the shape at runtime.
function isValidUser(obj) {
  return typeof obj.name === "string" && obj.name.length > 0 &&
         typeof obj.age === "number";
}
console.log(
  isValidUser({ name: "Roli", age: 19 }) + "," +
  isValidUser({ name: "Roli" }) + "," +
  isValidUser({ name: "", age: 19 })
);

