// TypeScript: interface Admin extends User { role: string }
function isAdmin(obj) {
  const userOk = typeof obj.name === "string" && obj.name.length > 0 &&
                 typeof obj.age === "number";
  return userOk && typeof obj.role === "string" && obj.role.length > 0;
}
console.log(
  isAdmin({ name: "R", age: 20, role: "owner" }) + "," +
  isAdmin({ name: "R", age: 20 })
);

